//! Finite inspection causes. Native authority detail retains separate priority.
const d = @import("transit_protocol").Diagnostic;
pub const Class = struct { code: []const u8, category: d.Category, message: []const u8, action: d.ActionKind };
pub const Entry = struct { cause: anyerror, code: []const u8, category: d.Category, message: []const u8, action: d.ActionKind };
pub const entries = [_]Entry{
    .{ .cause = error.AccessDenied, .code = "inspection.denied", .category = .access, .message = "Current authority denied this inspection. Check Board's configured read grant and the selected resource. This failure says nothing about whether earlier work applied.", .action = .inspect_scope },
