    .{ .cause = error.QuerySourceUnavailable, .code = "inspection.resource_unavailable", .category = .lifecycle, .message = "The required source resource is unavailable or no longer active. Inspect its current lifecycle and retained evidence. This does not establish physical cleanup or change an earlier operation's outcome.", .action = .inspect_scope },
    .{ .cause = error.ExchangeUnavailable, .code = "inspection.resource_unavailable", .category = .lifecycle, .message = "The required source resource is unavailable or no longer active. Inspect its current lifecycle and retained evidence. This does not establish physical cleanup or change an earlier operation's outcome.", .action = .inspect_scope },
    .{ .cause = error.ResourceUnavailable, .code = "inspection.resource_unavailable", .category = .lifecycle, .message = "The required source resource is unavailable or no longer active. Inspect its current lifecycle and retained evidence. This does not establish physical cleanup or change an earlier operation's outcome.", .action = .inspect_scope },
