    .{ .cause = error.ConnectionResetByPeer, .code = "inspection.authority_unavailable", .category = .unavailable, .message = "No complete authority observation was received. Retry the read when available; previously observed results remain separate and any earlier operation keeps its original outcome.", .action = .retry_read },
    .{ .cause = error.NetworkUnreachable, .code = "inspection.authority_unavailable", .category = .unavailable, .message = "No complete authority observation was received. Retry the read when available; previously observed results remain separate and any earlier operation keeps its original outcome.", .action = .retry_read },
    .{ .cause = error.EndOfStream, .code = "inspection.read_truncated", .category = .unavailable, .message = "Required bytes ended before the inspection completed. This cause alone does not identify truncated transport or encoded evidence. No complete observation is available; preserve the original object and read selector.", .action = .retry_read },
    .{ .cause = error.InvalidAuthorityResponse, .code = "inspection.invalid_authority_response", .category = .integrity, .message = "The authority response did not match the current contract or request. No candidate observation is usable. Inspect the peer definitions and preserved cause before retrying.", .action = .contact_operator },
    .{ .cause = error.InvalidObservation, .code = "inspection.invalid_authority_response", .category = .integrity, .message = "The authority response did not match the current contract or request. No candidate observation is usable. Inspect the peer definitions and preserved cause before retrying.", .action = .contact_operator },
    .{ .cause = error.OutOfMemory, .code = "inspection.memory_unavailable", .category = .unavailable, .message = "Board could not allocate memory to complete this bounded inspection. No complete observation was returned; existing accepted work is unaffected.", .action = .retry_read },
