    .{ .cause = error.InvalidExchangeFailure, .code = "inspection.invalid_exchange_failure", .category = .integrity, .message = "The retained exchange failure does not match its original input, closure or recorded effect identity. Preserve the original exchange evidence; this mismatch does not authorize another external dispatch.", .action = .contact_operator },
    .{ .cause = error.IncompatibleDefinition, .code = "inspection.incompatible_definition", .category = .integrity, .message = "The peer or retained evidence uses a different contract definition. Use matching binaries and preserve the original material; no fallback reinterprets accepted work.", .action = .contact_operator },
